// LibraryOverlap Read-only per-seed library overlap fact, computed by the server from the placements the library already holds. It only reads: it creates no placement, reserves no path and produces no WorkItem, and it is a fact rather than a plan, so pending_files counts files this seed would still have to write without promising that write. undetermined is a first-class answer and is never folded into absent: it means the overlap cannot be decided (no write set to compare, or a server with no library facts to read at all), and both counts and every per-file in_library value are then null.
type LibraryOverlap struct {
	// PendingFiles Number of write-set files the library does not hold yet. Null exactly when verdict is undetermined.
	PendingFiles *int `json:"pending_files"`

	// PresentFiles Number of write-set files whose rendered target the library already holds. Null exactly when verdict is undetermined.
	PresentFiles *int `json:"present_files"`

	// ReasonCode Stable code explaining an undetermined verdict. Null when the verdict needs no explanation. no_rendered_targets: this seed's write set cannot be compared, because its structure was never established (its torrent facts were not acquired, or it carries no file row at all) or because a file it would place has no rendered target. library_unavailable: the server has no library facts to read at all, so no overlap can be decided.
	ReasonCode *string `json:"reason_code"`

	// Verdict present: at least one file of this seed's write set already has its rendered target held by the library. absent: every write-set file's target is decidable and none is held. undetermined: the overlap cannot be decided for this seed.
	Verdict LibraryOverlapVerdict `json:"verdict"`
}

// LibraryOverlapVerdict present: at least one file of this seed's write set already has its rendered target held by the library. absent: every write-set file's target is decidable and none is held. undetermined: the overlap cannot be decided for this seed.
type LibraryOverlapVerdict string

