// OneShotInputSnapshot Complete admission input retained by the one-shot marker for durable UI readback. A saved-revision admission freezes the exact saved candidate revision, selected seed, complete effective sections, provenance, parser evidence and target facts. A current_input admission freezes the captured unsaved draft (draft + draft_digest) with input_source=current_input and null candidate_id/revision; the resolved effective sections and the global parser-policy default read at admission time are the execution identity. Legacy marker rows may return null.
type OneShotInputSnapshot struct {
	CandidateId *ID `json:"candidate_id"`

	// ConfigIdentity Explicit immutable configuration identity used for admission. A candidate revision is identified by candidate_id plus revision; a direct instance is identified by its materialized managed_anime_id; a captured unsaved current_input admission carries only its effective_digest. The CAS version is deliberately not an identity field.
	ConfigIdentity ConfigRevisionIdentity `json:"config_identity"`

	// Draft The captured unsaved draft of a current_input admission.
	Draft *AnimeDraft `json:"draft"`

	// DraftDigest Canonical digest of the captured draft; the replay identity input.
	DraftDigest       *string                `json:"draft_digest"`
	EffectiveDigest   string                 `json:"effective_digest"`
	EffectiveSections map[string]interface{} `json:"effective_sections"`

	// EpisodeOffset The frozen one-shot episode offset from the admission request. Legacy marker rows omit it.
	EpisodeOffset *int `json:"episode_offset,omitempty"`

	// InputSource Config input source of the captured admission; null for the legacy saved-revision spelling.
	InputSource     *OneShotInputSnapshotInputSource `json:"input_source"`
	Parser          *ParserProvenance                `json:"parser"`
	Revision        *int64                           `json:"revision"`
	SectionSchemas  map[string]string                `json:"section_schemas"`
	SectionVersions map[string]int64                 `json:"section_versions"`

	// SelectedSeed One selected seed as frozen into a one-shot input snapshot (always the resolved locator form; see SelectedSeedInput for the request). For a provider=custom seed the entry/group refs are the frozen custom-source and custom-group identities of a custom/oneshot draft source's own feed snapshot, never a discoverable provider entry. provider/provider_entry_ref/provider_group_ref are provenance and authorization facts; title/published_at/size_bytes are frozen snapshot facts; neither group alone is content identity. At least one strong content identity is mandatory: a canonical info_hash or a SHA-256 expected_payload_digest. When both are supplied both must match the fetched torrent exactly.
	SelectedSeed SelectedSeed         `json:"selected_seed"`
	TargetFacts  *TargetFactsSnapshot `json:"target_facts"`
}

